const body = $json.body;
const data = body.data || {};
const key = data.key || {};
const message = data.message || {};

const text = message.conversation
  || (message.extendedTextMessage && message.extendedTextMessage.text)
  || (message.buttonsResponseMessage && message.buttonsResponseMessage.selectedDisplayText)
  || (message.listResponseMessage && message.listResponseMessage.title)
  || '';

const remoteJid = key.remoteJid || '';
// Skip group messages
if (remoteJid.includes('@g.us')) return [];

const phone = remoteJid.replace('@s.whatsapp.net', '');

return [{ json: {
  phone,
  name: data.pushName || 'Pelanggan',
  message: text,
  messageLower: text.toLowerCase().trim(),
  instance: body.instance || $env.EVOLUTION_INSTANCE,
  messageId: key.id
}}];

const msgData = $('Extract Message Data').item.json;
const sessionItems = $input.all();

const phone = msgData.phone;
const name = msgData.name;
const msg = msgData.messageLower;
const originalMsg = msgData.message;
const instance = msgData.instance;

let session = {};
if (sessionItems.length > 0 && sessionItems[0].json && sessionItems[0].json.phone) {
  session = sessionItems[0].json;
}
const state = session.state || 'start';

// ─── MESSAGE TEMPLATES ───────────────────────────────────────────
function mainMenu(name) {
  return `*RESTORAN SASAK LOMBOK*
Halo, ${name}! Selamat datang!

Masakan khas Lombok yang otentik & lezat

Silakan pilih menu:
1 - Lihat Menu Makanan
2 - Pesan Makanan
3 - Reservasi Meja
4 - Jam Operasional
5 - Lokasi & Alamat
6 - Hubungi Kami

Ketik angka untuk memilih`;
}

function foodMenu() {
  return `*MENU RESTORAN SASAK LOMBOK*

*AYAM TALIWANG & PELECING*
- Ayam Taliwang Pedas: Rp 45.000
- Ayam Taliwang Tidak Pedas: Rp 45.000
- Pelecing Ayam: Rp 40.000

*SATE KHAS LOMBOK*
- Sate Rembiga: Rp 35.000
- Sate Ayam Bulayak: Rp 30.000

*SAYURAN*
- Plecing Kangkung: Rp 20.000
- Beberuk Terong: Rp 15.000
- Urap Sayur: Rp 18.000

*NASI & LAUK*
- Nasi Balap Puyung: Rp 25.000
- Nasi Putih: Rp 5.000

*IKAN*
- Ikan Bakar Bumbu Lombok: Rp 55.000
- Ikan Goreng Pedas: Rp 50.000

*MINUMAN*
- Es Kelapa Muda: Rp 15.000
- Es Teh Manis: Rp 8.000
- Es Jeruk: Rp 10.000
- Air Mineral: Rp 5.000

Untuk memesan ketik *2* atau *pesan*`;
}

const GREET = ['halo','hai','hello','hi','mulai','start','help','menu','0','batal','kembali','home'];

let responseText = '';
let newState = state;
let sessionUpdate = {};

// Reset ke menu utama
if (GREET.includes(msg)) {
  responseText = mainMenu(name);
  newState = 'main_menu';
}
// ─── MAIN MENU ───────────────────────────────────────────────────
else if (state === 'start' || state === 'main_menu') {
  if (msg === '1' || msg.includes('lihat menu')) {
    responseText = foodMenu();
  } else if (msg === '2' || msg.includes('pesan') || msg.includes('order')) {
    responseText = '*PESAN MAKANAN*

Ketik pesanan kamu, contoh:
2 Ayam Taliwang Pedas, 1 Plecing Kangkung, 2 Es Kelapa Muda

Lihat menu dulu? Ketik *1*
Ketik *0* untuk batal';
    newState = 'ordering';
  } else if (msg === '3' || msg.includes('reservasi') || msg.includes('booking')) {
    responseText = '*RESERVASI MEJA*

Berapa orang yang akan datang?
Contoh: 4

Ketik *0* untuk batal';
    newState = 'reservation_guests';
  } else if (msg === '4' || msg.includes('jam') || msg.includes('buka')) {
    responseText = '*JAM OPERASIONAL*

Senin - Minggu
10.00 - 22.00 WITA

Ketik *0* untuk menu utama';
  } else if (msg === '5' || msg.includes('lokasi') || msg.includes('alamat')) {
    responseText = `*LOKASI*

${$env.RESTAURANT_ADDRESS}

Google Maps: ${$env.RESTAURANT_MAPS}

Ketik *0* untuk menu utama`;
  } else if (msg === '6' || msg.includes('hubungi') || msg.includes('kontak')) {
    responseText = `*HUBUNGI KAMI*

WhatsApp: ${$env.RESTAURANT_PHONE}
Instagram: @restoran.sasak.lombok

Jam 10.00 - 22.00 WITA`;
  } else {
    responseText = mainMenu(name);
    newState = 'main_menu';
  }
}
// ─── ORDERING ────────────────────────────────────────────────────
else if (state === 'ordering') {
  if (originalMsg && originalMsg.length > 3) {
    sessionUpdate.pending_order = originalMsg;
    responseText = `*KONFIRMASI PESANAN*

Pesanan kamu:
${originalMsg}

Sudah benar?
Ketik *ya* untuk konfirmasi
Ketik *tidak* untuk ubah
Ketik *0* untuk batal`;
    newState = 'order_confirm';
  } else {
    responseText = 'Masukkan pesanan kamu, contoh:
2 Ayam Taliwang, 1 Plecing Kangkung

Ketik *0* untuk batal';
  }
}
else if (state === 'order_confirm') {
  if (['ya','yes','iya'].includes(msg)) {
    responseText = 'Siapa nama pemesan?

Ketik *0* untuk batal';
    newState = 'order_name';
  } else if (['tidak','no','bukan'].includes(msg)) {
    responseText = 'Silakan ketik ulang pesanan kamu:

Ketik *0* untuk batal';
    newState = 'ordering';
  } else {
    responseText = 'Ketik *ya* untuk konfirmasi atau *tidak* untuk ubah pesanan';
  }
}
else if (state === 'order_name') {
  if (originalMsg && originalMsg.length > 1) {
    sessionUpdate.order_customer_name = originalMsg;
    responseText = `Halo ${originalMsg}! Pesanan untuk:

1 - Makan di tempat (Dine-in)
2 - Bawa pulang (Take-away)

Ketik *1* atau *2*`;
    newState = 'order_type';
  }
}
else if (state === 'order_type') {
  const isDineIn = msg === '1' || msg.includes('dine') || msg.includes('tempat');
  const isTakeAway = msg === '2' || msg.includes('bawa') || msg.includes('take');
  if (isDineIn || isTakeAway) {
    const tipe = isDineIn ? 'Makan di tempat' : 'Bawa pulang';
    sessionUpdate.order_type = isDineIn ? 'dine-in' : 'take-away';
    const cname = session.order_customer_name || sessionUpdate.order_customer_name || '-';
    const items = session.pending_order || '-';
    responseText = `*KONFIRMASI AKHIR*

Pesanan: ${items}
Nama: ${cname}
Tipe: ${tipe}

Ketik *konfirmasi* untuk selesai
Ketik *0* untuk batal`;
    newState = 'order_final';
  } else {
    responseText = 'Ketik *1* untuk makan di tempat atau *2* untuk bawa pulang';
  }
}
else if (state === 'order_final') {
  if (msg === 'konfirmasi' || msg === 'ya' || msg === 'yes') {
    const orderId = 'ORD-' + Date.now().toString().slice(-6);
    sessionUpdate.last_order_id = orderId;
    sessionUpdate.order_status = 'confirmed';
    responseText = `*PESANAN BERHASIL!*

Nomor Pesanan: *${orderId}*
Estimasi: 30-45 menit

Terima kasih sudah memesan di Restoran Sasak Lombok!

Ketik *0* untuk menu utama`;
    newState = 'main_menu';
  } else {
    responseText = 'Ketik *konfirmasi* untuk selesaikan atau *0* untuk batal';
  }
}
// ─── RESERVATION ─────────────────────────────────────────────────
else if (state === 'reservation_guests') {
  const n = parseInt((msg.match(/\d+/) || [])[0]);
  if (n >= 1 && n <= 50) {
    sessionUpdate.reservation_guests = String(n);
    responseText = 'Tanggal kedatangan?
Contoh: 25 Juni 2025

Ketik *0* untuk batal';
    newState = 'reservation_date';
  } else {
    responseText = 'Masukkan jumlah tamu (1-50), contoh: 4';
  }
}
else if (state === 'reservation_date') {
  if (originalMsg && originalMsg.length > 2) {
    sessionUpdate.reservation_date = originalMsg;
    responseText = 'Jam kedatangan?
Contoh: 19:00

Ketik *0* untuk batal';
    newState = 'reservation_time';
  } else {
    responseText = 'Masukkan tanggal, contoh: 25 Juni 2025';
  }
}
else if (state === 'reservation_time') {
  if (originalMsg && originalMsg.length > 1) {
    sessionUpdate.reservation_time = originalMsg;
    responseText = 'Nama untuk reservasi?

Ketik *0* untuk batal';
    newState = 'reservation_name';
  } else {
    responseText = 'Masukkan jam kedatangan, contoh: 19:00';
  }
}
else if (state === 'reservation_name') {
  if (originalMsg && originalMsg.length > 1) {
    const resId = 'RES-' + Date.now().toString().slice(-6);
    sessionUpdate.reservation_name = originalMsg;
    sessionUpdate.last_reservation_id = resId;
    const g = session.reservation_guests || sessionUpdate.reservation_guests || '-';
    const d = session.reservation_date || sessionUpdate.reservation_date || '-';
    const t = session.reservation_time || sessionUpdate.reservation_time || '-';
    responseText = `*KONFIRMASI RESERVASI*

Nomor: *${resId}*
Nama: ${originalMsg}
Tamu: ${g} orang
Tanggal: ${d}
Jam: ${t}

Ketik *ya* untuk konfirmasi
Ketik *tidak* untuk ulang
Ketik *0* untuk batal`;
    newState = 'reservation_confirm';
  }
}
else if (state === 'reservation_confirm') {
  if (['ya','yes','iya'].includes(msg)) {
    sessionUpdate.reservation_status = 'confirmed';
    const rname = session.reservation_name || sessionUpdate.reservation_name || '-';
    const resId = session.last_reservation_id || sessionUpdate.last_reservation_id || '-';
    responseText = `*RESERVASI BERHASIL!*

Nomor: *${resId}*
Nama: ${rname}

Sampai jumpa di Restoran Sasak Lombok!
Info: ${$env.RESTAURANT_PHONE}

Ketik *0* untuk menu utama`;
    newState = 'main_menu';
  } else if (['tidak','no'].includes(msg)) {
    responseText = 'Baik, mulai ulang reservasi.

Berapa orang yang akan datang?';
    newState = 'reservation_guests';
  } else {
    responseText = 'Ketik *ya* untuk konfirmasi atau *tidak* untuk mulai ulang';
  }
}
else {
  responseText = mainMenu(name);
  newState = 'main_menu';
}

return [{ json: {
  phone, name, instance, responseText, newState,
  sessionUpdate: {
    ...sessionUpdate,
    state: newState,
    last_updated: new Date().toISOString()
  },
  currentSession: session
}}];

const d = $('Route & Build Response').item.json;
const s = d.currentSession;
const su = d.sessionUpdate;
const orderId = su.last_order_id || s.last_order_id;
const cname = su.order_customer_name || s.order_customer_name;
const items = s.pending_order;
const otype = su.order_type || s.order_type;
const now = new Date().toLocaleString('id-ID', {timeZone: 'Asia/Makassar'});
return [{ json: {
  order_id: orderId,
  phone: d.phone,
  customer_name: cname,
  items,
  order_type: otype,
  status: 'confirmed',
  order_time: new Date().toISOString(),
  kitchen_msg: `*PESANAN BARU!*\nNo: ${orderId}\nNama: ${cname}\nHP: ${d.phone}\nPesanan: ${items}\nTipe: ${otype}\nWaktu: ${now}`
}}];

const d = $('Route & Build Response').item.json;
const s = d.currentSession;
const su = d.sessionUpdate;
const resId = su.last_reservation_id || s.last_reservation_id;
const rname = su.reservation_name || s.reservation_name;
const guests = su.reservation_guests || s.reservation_guests;
const date = su.reservation_date || s.reservation_date;
const time = su.reservation_time || s.reservation_time;
return [{ json: {
  reservation_id: resId,
  phone: d.phone,
  customer_name: rname,
  guests,
  date,
  time,
  status: 'confirmed',
  created_at: new Date().toISOString(),
  owner_msg: `*RESERVASI BARU!*\nNo: ${resId}\nNama: ${rname}\nHP: ${d.phone}\nTamu: ${guests} orang\nTanggal: ${date}\nJam: ${time}`
}}];
